package com.ips.ui;
import com.ips.dao.FeatureDAO;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.sql.SQLException;import java.util.List;
public class AdminFrame extends JFrame{
 private final FeatureDAO dao=new FeatureDAO();private final DefaultListModel<String> model=new DefaultListModel<>();private final JList<String> list=new JList<>(model);private List<String[]> rows=List.of();
 public AdminFrame(){UIStyle.configureFrame(this,"Admin | Question Bank",900,600);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(14,14));root.setBackground(UIStyle.BACKGROUND);root.setBorder(new EmptyBorder(22,24,22,24));root.add(UIStyle.heading("Question bank management"),BorderLayout.NORTH);list.setFont(new Font("SansSerif",Font.PLAIN,14));list.setCellRenderer((l,v,i,s,f)->{JLabel x=new JLabel("  "+v);x.setOpaque(true);x.setBorder(new EmptyBorder(9,8,9,8));x.setBackground(s?new Color(67,78,112):UIStyle.PANEL);x.setForeground(UIStyle.TEXT);return x;});root.add(new JScrollPane(list),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));actions.setBackground(UIStyle.BACKGROUND);JButton add=UIStyle.primaryButton("Add question"),edit=UIStyle.primaryButton("Edit selected"),del=UIStyle.primaryButton("Delete selected"),refresh=UIStyle.linkButton("Refresh");add.addActionListener(e->editQuestion(null));edit.addActionListener(e->{int i=list.getSelectedIndex();if(i>=0)editQuestion(rows.get(i));});del.addActionListener(e->delete());refresh.addActionListener(e->load());actions.add(refresh);actions.add(add);actions.add(edit);actions.add(del);root.add(actions,BorderLayout.SOUTH);setContentPane(root);load();}
 private void load(){try{rows=dao.allQuestions();model.clear();for(String[] r:rows)model.addElement("#"+r[0]+" | "+r[1]+" | "+r[2]+" | "+r[3]);}catch(SQLException e){error(e);}}
 private void delete(){int i=list.getSelectedIndex();if(i<0)return;if(JOptionPane.showConfirmDialog(this,"Delete this question? Existing attempt records may prevent deletion.","Confirm delete",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{dao.deleteQuestion(Long.parseLong(rows.get(i)[0]));load();}catch(SQLException e){error(e);}}
 private void editQuestion(String[] row){boolean editing=row!=null;JTextField category=new JTextField(editing?row[1]:"Java"),text=new JTextField(editing?row[3]:"");JComboBox<String> difficulty=new JComboBox<>(new String[]{"Easy","Medium","Hard"});if(editing)difficulty.setSelectedItem(row[2]);JTextField a=new JTextField(),b=new JTextField(),c=new JTextField(),d=new JTextField(),explanation=new JTextField();JComboBox<String> correct=new JComboBox<>(new String[]{"A","B","C","D"});
 if(editing)try{var q=dao.getQuestion(Long.parseLong(row[0]));if(q!=null){text.setText(q.getQuestionText());a.setText(q.getOption("A"));b.setText(q.getOption("B"));c.setText(q.getOption("C"));d.setText(q.getOption("D"));correct.setSelectedItem(q.getCorrectOption());explanation.setText(q.getExplanation());}}catch(SQLException e){error(e);return;}
 JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel("Category"));form.add(category);form.add(new JLabel("Difficulty"));form.add(difficulty);form.add(new JLabel("Question"));form.add(text);form.add(new JLabel("Option A"));form.add(a);form.add(new JLabel("Option B"));form.add(b);form.add(new JLabel("Option C"));form.add(c);form.add(new JLabel("Option D"));form.add(d);form.add(new JLabel("Correct option"));form.add(correct);form.add(new JLabel("Explanation"));form.add(explanation);JScrollPane scroll=new JScrollPane(form);scroll.setPreferredSize(new Dimension(560,360));if(JOptionPane.showConfirmDialog(this,scroll,editing?"Edit question":"Add question",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return;
 try{if(category.getText().isBlank()||text.getText().isBlank()||a.getText().isBlank()||b.getText().isBlank()||c.getText().isBlank()||d.getText().isBlank()){JOptionPane.showMessageDialog(this,"Fill in category, question, and all four options.");return;}dao.saveQuestion(category.getText().trim(),(String)difficulty.getSelectedItem(),text.getText().trim(),a.getText().trim(),b.getText().trim(),c.getText().trim(),d.getText().trim(),(String)correct.getSelectedItem(),explanation.getText().trim(),editing?Long.valueOf(row[0]):null);load();}catch(SQLException e){error(e);}}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Database error",JOptionPane.ERROR_MESSAGE);}
}
